#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    cin >> n >> mod;

    vector<long long> sequence = {0, 1};
    long long total_value = 1;

    for (int i = 2; i <= n; ++i) {
        int limit = (int) sqrt(i) + 1;
        long long current_sum = total_value;
        for (int f = 2; f < limit; ++f) {
            current_sum = (current_sum + sequence[i / f]) % mod;
        }
        int boundary = i;
        for (int j = 1; j <= i / limit; ++j) {
            int next_idx = i / (j + 1);
            current_sum = (current_sum + (boundary - next_idx) * sequence[j]) % mod;
            boundary = next_idx;
        }
        total_value = (total_value + current_sum) % mod;
        sequence.push_back(current_sum);
    }

    cout << sequence.back() << "\n";

    return 0;
}
